import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"角色设定与参数配置 (Personality & Parameters)","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/tools/llm-chat/agents/parameters.md","filePath":"user-guide/tools/llm-chat/agents/parameters.md","lastUpdated":1784437941000}'),l={name:"user-guide/tools/llm-chat/agents/parameters.md"};function n(s,e,i,g,d,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="角色设定与参数配置-personality-parameters" tabindex="-1">角色设定与参数配置 (Personality &amp; Parameters) <a class="header-anchor" href="#角色设定与参数配置-personality-parameters" aria-label="Permalink to &quot;角色设定与参数配置 (Personality &amp; Parameters)&quot;">​</a></h1><p>这是 Agent 的“灵魂”所在，通过配置模型、预设消息、关联资源和 Knowledge 访问权限，定义 Agent 的行为逻辑和资料边界。</p><h2 id="_1-核心设定" tabindex="-1">1. 核心设定 <a class="header-anchor" href="#_1-核心设定" aria-label="Permalink to &quot;1. 核心设定&quot;">​</a></h2><ul><li><strong>模型配置</strong>: 为该 Agent 指定默认的服务渠道（Profile）和模型 ID。你可以为不同 Agent 分配擅长不同领域的模型。</li><li><strong>关联用户档案</strong>: 绑定特定的<a href="./user-profiles">用户档案</a>，在发送请求时自动注入用户姓名、性格、背景等信息，实现个性化交互。</li><li><strong>预设消息 (Presets)</strong>: <ul><li><strong>角色定义</strong>: 支持 <code>system</code> (系统提示)、<code>user</code> (用户示例)、<code>assistant</code> (助手示例)。</li><li><strong>注入策略</strong>: <ul><li><strong>深度 (Depth)</strong>: 控制消息插入到对话历史的深度。</li><li><strong>高级深度</strong>: 支持多点或循环语法（如 <code>3, 10~5</code>），实现极其复杂的上下文排布。</li><li><strong>锚点 (Anchor)</strong>: 将消息固定在上下文的特定位置（如最顶部或最底部）。</li></ul></li><li><strong>开场白显示</strong>: 设置前 N 条预设消息在聊天界面中作为“开场白”展示，方便快速进入状态。</li></ul></li></ul><h2 id="_2-关联资源" tabindex="-1">2. 关联资源 <a class="header-anchor" href="#_2-关联资源" aria-label="Permalink to &quot;2. 关联资源&quot;">​</a></h2><p>Agent 可以通过关联其他子系统来增强能力：</p><ul><li><strong>快捷操作</strong>: 关联<a href="./../quick-actions/index">快捷操作组</a>。激活该 Agent 后，对应的快捷按钮将直接出现在输入框上方。</li><li><strong>世界书 (Worldbook)</strong>: 关联<a href="./../worldbook/index">世界书</a>，实现关键词自动触发背景设定注入。 <ul><li><strong>禁用递归扫描</strong>: 防止世界书条目互相触发导致的上下文爆炸。</li><li><strong>扫描深度</strong>: 控制系统回溯多少条历史消息来匹配关键词。</li></ul></li></ul><h2 id="_3-knowledge-资料访问权限" tabindex="-1">3. Knowledge 资料访问权限 <a class="header-anchor" href="#_3-knowledge-资料访问权限" aria-label="Permalink to &quot;3. Knowledge 资料访问权限&quot;">​</a></h2><p>在 <strong>「知识库 (Knowledge) -&gt; Knowledge 资料访问权限」</strong> 中配置 Agent 是否可以按需使用资料库：</p><ul><li><strong>启用 Knowledge</strong>：关闭时不会暴露 Knowledge 工具，也不会展开资料库目录。</li><li><strong>允许资料库</strong>：只保存稳定的 library ID，资料库改名后授权不会失效。</li><li><strong>允许全库搜索</strong>：未指定库时是否可以搜索全部已授权库。</li><li><strong>允许文档读取</strong>：是否可以从命中继续读取 chunk 邻域或文档范围。</li><li><strong>允许研究任务</strong>：是否可以启动有轮次、证据和成本预算的多轮研究。</li></ul><p>检索策略、Top-K、过滤器、证据字符预算等属于本次 <code>knowledge.search</code> / <code>knowledge.read</code> / <code>knowledge.research</code> 调用参数，不会改变 Agent 的长期授权。</p><h2 id="_4-模型高级参数" tabindex="-1">4. 模型高级参数 <a class="header-anchor" href="#_4-模型高级参数" aria-label="Permalink to &quot;4. 模型高级参数&quot;">​</a></h2><p>在「模型参数编辑器」中，你可以精细调整模型的生成行为：</p><ul><li><strong>基础参数</strong>: Temperature (随机性)、Top P、Max Tokens。</li><li><strong>惩罚参数</strong>: Frequency Penalty (频率惩罚)、Presence Penalty (存在惩罚)。</li><li><strong>安全设置</strong>: 配置模型的内容过滤级别（Hate, Harassment, Sexually Explicit 等）。</li><li><strong>后处理 (Post-processing)</strong>: <ul><li><strong>停止词 (Stop Sequences)</strong>: 遇到特定字符串时停止生成。</li><li><strong>逻辑偏置 (Logit Bias)</strong>: 强制模型更多或更少地使用特定 Token。</li></ul></li></ul><hr><h3 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h3><ul><li><a href="./../context-pipeline/context-compression">上下文压缩配置</a></li><li><a href="./assets">Agent 资产管理</a></li><li><a href="./../quick-actions/template-syntax">快捷操作模板语法</a></li></ul>',17)])])}const p=t(l,[["render",n]]);export{h as __pageData,p as default};
